args <- commandArgs(trailingOnly=TRUE)
if(length(args)!=2) stop("Usage: Rscript paired_process_qc.R samples.tsv output_directory")
x <- read.delim(args[1],sep="\t",check.names=FALSE,stringsAsFactors=FALSE)
required <- c("pair_id","biological_sample_id","library_id","arm","clean_reads","spike_reads","spike_input_fmol")
if(!all(required %in% names(x)) || anyDuplicated(x$library_id)) stop("Missing columns or duplicated library ID")
if(any(!is.finite(as.matrix(x[,c("clean_reads","spike_reads","spike_input_fmol")])))) stop("Nonfinite numeric input")
if(any(x$clean_reads<=0 | x$spike_reads<0 | x$spike_reads>x$clean_reads | x$spike_input_fmol<0)) stop("Invalid counts/dose")
if(any(is.na(x$biological_sample_id) | x$biological_sample_id %in% c("","unknown"))) stop("Biological identity required for pairing")
pairs <- split(x,x$pair_id)
for(pair in pairs) if(nrow(pair)!=2 || !setequal(pair$arm,c("control","test")) || length(unique(pair$biological_sample_id))!=1) stop("Each pair must contain one control and one test from the same biological sample")
x$spike_RPM <- 1e6*x$spike_reads/x$clean_reads
summary <- do.call(rbind,lapply(split(x,x$pair_id),function(pair) data.frame(pair_id=pair$pair_id[1],biological_sample_id=pair$biological_sample_id[1],observed_RPM_test_minus_control=pair$spike_RPM[pair$arm=="test"]-pair$spike_RPM[pair$arm=="control"],scope="paired process QC; not molecular recovery or population inference")))
if(file.exists(args[2])) stop("Output directory exists; refusing stale overwrite")
dir.create(args[2],recursive=TRUE)
write.table(x,file.path(args[2],"spike_signal.tsv"),sep="\t",quote=FALSE,row.names=FALSE)
write.table(summary,file.path(args[2],"paired_process_qc.tsv"),sep="\t",quote=FALSE,row.names=FALSE)
writeLines(c("# 配对工艺 QC",paste("独立生物学样本数：",length(unique(x$biological_sample_id))),paste("工艺配对数：",length(pairs)),"仅报告观察到的 spike-in 信号；不换算分子回收率，不作总体生物学推断。"),file.path(args[2],"README.md"))
